sp_widget.client_script:
api.controller=function($scope) {

    var c = this;


    // ==============================
    // Default section
    // ==============================

    c.activeSection = 'dashboard';


    // ==============================
    // Selected assignment
    // ==============================

    c.selectedAssignment = null;


    // ==============================
    // Sidebar navigation
    // ==============================

    c.selectSection = function(section) {

        c.activeSection = section;

        c.selectedAssignment = null;

    };


    // ==============================
    // Open assignment
    // ==============================

    c.openAssignment = function(ticket) {

        c.selectedAssignment = ticket;

        // Automatically move to
        // My Assignments section

        c.activeSection = 'assignments';

    };


    // ==============================
    // Close assignment details
    // ==============================

    c.closeAssignment = function() {

        c.selectedAssignment = null;

    };


    // ==============================
    // Priority CSS
    // ==============================

    c.getPriorityClass = function(priority) {

        if (!priority) {
            return 'other';
        }


        priority = priority.toLowerCase();


        if (priority === 'high') {

            return 'high';

        }


        if (priority === 'medium') {

            return 'medium';

        }


        if (priority === 'low') {

            return 'low';

        }


        return 'other';

    };


    // ==============================
    // Status CSS
    // ==============================

    c.getStatusClass = function(status) {

        if (!status) {
            return 'other';
        }


        status = status.toLowerCase();


        if (status.indexOf('pending') !== -1) {

            return 'pending';

        }


        if (
            status.indexOf('progress') !== -1
        ) {

            return 'progress';

        }


        if (
            status.indexOf('resolved') !== -1
        ) {

            return 'resolved';

        }


        return 'other';

    };


    // ==============================
    // Feedback
    // ==============================

    c.showFeedback = function() {

        // Feedback section will be
        // connected later.

        alert('Feedback section will be connected soon.');

    };

}

sp_widget.css:
/* =========================
   MAIN LAYOUT
   ========================= */

.staff-dashboard {
    display: flex;
    min-height: calc(100vh - 70px);
    background: #f5f7fb;
}


/* =========================
   SIDEBAR
   ========================= */

.sidebar {
    width: 240px;
    background: #ffffff;
    border-right: 1px solid #e5e7eb;

    display: flex;
    flex-direction: column;
    justify-content: space-between;

    flex-shrink: 0;
}


.sidebar-menu {
    padding: 25px 15px;
}


.menu-item {
    padding: 13px 15px;
    margin-bottom: 8px;

    border-radius: 8px;

    color: #4b5563;

    font-size: 15px;
    font-weight: 500;

    cursor: pointer;

    transition: all 0.2s ease;
}


.menu-item:hover {
    background: #f3f4f6;
}


.menu-item.active {
    background: #eef2ff;
    color: #4f46e5;

    font-weight: 600;
}


/* =========================
   SIDEBAR USER
   ========================= */

.sidebar-user {
    border-top: 1px solid #e5e7eb;

    padding: 18px;

    display: flex;
    align-items: center;

    gap: 10px;
}


.sidebar-user-icon {
    width: 38px;
    height: 38px;

    border-radius: 50%;

    background: #eef2ff;

    display: flex;
    align-items: center;
    justify-content: center;
}


.sidebar-user-name {
    font-size: 14px;
    font-weight: 600;

    color: #1f2937;
}


.sidebar-user-role {
    font-size: 12px;

    color: #6b7280;

    margin-top: 2px;
}


/* =========================
   MAIN CONTENT
   ========================= */

.main-content {
    flex: 1;

    padding: 30px;

    overflow-x: hidden;
}


/* =========================
   WELCOME
   ========================= */

.welcome-section {
    margin-bottom: 25px;
}


.welcome-section h1 {
    margin: 0;

    font-size: 27px;

    color: #111827;
}


.welcome-section p {
    margin-top: 7px;

    color: #6b7280;

    font-size: 14px;
}


/* =========================
   KPI CARDS
   ========================= */

.kpi-grid {
    display: grid;

    grid-template-columns: repeat(4, 1fr);

    gap: 18px;

    margin-bottom: 25px;
}


.kpi-card {
    background: #ffffff;

    border: 1px solid #e5e7eb;

    border-radius: 10px;

    padding: 20px;

    box-shadow: 0 2px 6px rgba(0, 0, 0, 0.04);
}


.kpi-icon {
    font-size: 23px;

    margin-bottom: 10px;
}


.kpi-title {
    font-size: 13px;

    color: #6b7280;

    margin-bottom: 5px;
}


.kpi-value {
    font-size: 25px;

    font-weight: 700;

    color: #111827;
}


/* =========================
   CONTENT CARD
   ========================= */

.content-card {
    background: #ffffff;

    border: 1px solid #e5e7eb;

    border-radius: 10px;

    padding: 22px;

    margin-bottom: 25px;

    box-shadow: 0 2px 6px rgba(0, 0, 0, 0.04);
}


.section-header h2 {
    margin: 0;

    font-size: 19px;

    color: #111827;
}


.section-header p {
    margin-top: 5px;

    color: #6b7280;

    font-size: 13px;
}


/* =========================
   TABLE
   ========================= */

.table-container {
    width: 100%;

    overflow-x: auto;

    margin-top: 18px;
}


table {
    width: 100%;

    border-collapse: collapse;

    min-width: 700px;
}


th {
    text-align: left;

    padding: 12px;

    background: #f9fafb;

    color: #6b7280;

    font-size: 12px;

    font-weight: 600;

    border-bottom: 1px solid #e5e7eb;
}


td {
    padding: 14px 12px;

    color: #374151;

    font-size: 13px;

    border-bottom: 1px solid #f0f0f0;
}


tr:last-child td {
    border-bottom: none;
}


tbody tr {
    cursor: pointer;

    transition: background 0.2s ease;
}


tbody tr:hover {
    background: #f9fafb;
}


/* =========================
   STATUS
   ========================= */

.status {
    display: inline-block;

    padding: 5px 9px;

    border-radius: 15px;

    font-size: 11px;

    font-weight: 600;
}


.status.pending {
    background: #fef3c7;

    color: #92400e;
}


.status.progress {
    background: #dbeafe;

    color: #1e40af;
}


.status.resolved {
    background: #dcfce7;

    color: #166534;
}


.status.other {
    background: #f3f4f6;

    color: #374151;
}


/* =========================
   PRIORITY
   ========================= */

.priority {
    font-size: 12px;

    font-weight: 600;
}


.priority.high {
    color: #dc2626;
}


.priority.medium {
    color: #d97706;
}


.priority.low {
    color: #16a34a;
}


.priority.other {
    color: #6b7280;
}


/* =========================
   QUICK ACTIONS
   ========================= */

.quick-section h2 {
    font-size: 19px;

    margin-bottom: 15px;

    color: #111827;
}


.quick-grid {
    display: grid;

    grid-template-columns: repeat(2, 1fr);

    gap: 18px;
}


.quick-card {
    background: #ffffff;

    border: 1px solid #e5e7eb;

    border-radius: 10px;

    padding: 20px;

    text-align: left;

    cursor: pointer;

    display: flex;

    flex-direction: column;

    gap: 6px;

    transition: all 0.2s ease;
}


.quick-card:hover {
    transform: translateY(-2px);

    box-shadow: 0 5px 15px rgba(0, 0, 0, 0.08);
}


.quick-card span {
    font-size: 23px;
}


.quick-card strong {
    font-size: 15px;

    color: #111827;
}


.quick-card small {
    font-size: 12px;

    color: #6b7280;
}


/* =========================
   MY ASSIGNMENTS
   ========================= */

.page-title {
    margin-bottom: 25px;
}


.page-title h1 {
    margin: 0;

    font-size: 27px;

    color: #111827;
}


.page-title p {
    margin-top: 7px;

    color: #6b7280;

    font-size: 14px;
}


/* =========================
   ASSIGNMENT SUMMARY
   ========================= */

.assignment-summary {
    display: grid;

    grid-template-columns: repeat(3, 1fr);

    gap: 18px;

    margin-bottom: 25px;
}


.summary-card {
    background: #ffffff;

    border: 1px solid #e5e7eb;

    border-radius: 10px;

    padding: 18px;

    display: flex;

    align-items: center;

    gap: 14px;

    box-shadow: 0 2px 6px rgba(0, 0, 0, 0.04);
}


.summary-icon {
    width: 42px;
    height: 42px;

    border-radius: 9px;

    background: #f3f4f6;

    display: flex;

    align-items: center;

    justify-content: center;

    font-size: 21px;
}


.summary-title {
    color: #6b7280;

    font-size: 12px;

    margin-bottom: 3px;
}


.summary-value {
    color: #111827;

    font-size: 23px;

    font-weight: 700;
}


/* =========================
   ASSIGNMENT DETAILS
   ========================= */

.assignment-details {
    background: #ffffff;

    border: 1px solid #e5e7eb;

    border-radius: 10px;

    padding: 22px;

    margin-top: 25px;

    box-shadow: 0 2px 6px rgba(0, 0, 0, 0.04);
}


.details-header {
    display: flex;

    justify-content: space-between;

    align-items: center;

    margin-bottom: 25px;
}


.details-header h2 {
    margin: 0;

    font-size: 19px;

    color: #111827;
}


.details-header p {
    margin-top: 5px;

    color: #6b7280;

    font-size: 13px;
}


.back-button {
    border: 1px solid #d1d5db;

    background: #ffffff;

    color: #374151;

    padding: 9px 14px;

    border-radius: 7px;

    cursor: pointer;

    font-size: 13px;
}


.back-button:hover {
    background: #f3f4f6;
}


/* =========================
   DETAIL GRID
   ========================= */

.detail-grid {
    display: grid;

    grid-template-columns: repeat(3, 1fr);

    gap: 18px;

    margin-bottom: 20px;
}


.detail-item {
    background: #f9fafb;

    border-radius: 8px;

    padding: 15px;
}


.detail-item label,
.description-box label {
    display: block;

    font-size: 12px;

    color: #6b7280;

    margin-bottom: 6px;

    font-weight: 600;
}


.detail-item p {
    margin: 0;

    color: #111827;

    font-size: 14px;

    font-weight: 500;
}


/* =========================
   DESCRIPTION
   ========================= */

.description-box {
    background: #f9fafb;

    border-radius: 8px;

    padding: 16px;
}


.description-box p {
    margin: 0;

    color: #374151;

    font-size: 14px;

    line-height: 1.6;
}


/* =========================
   NO RECORDS
   ========================= */

.no-records {
    text-align: center;

    padding: 30px !important;

    color: #6b7280;
}


/* =========================
   RESPONSIVE
   ========================= */

@media (max-width: 1000px) {

    .kpi-grid {
        grid-template-columns: repeat(2, 1fr);
    }

    .detail-grid {
        grid-template-columns: repeat(2, 1fr);
    }

}


@media (max-width: 700px) {

    .staff-dashboard {
        flex-direction: column;
    }


    .sidebar {
        width: 100%;

        border-right: none;

        border-bottom: 1px solid #e5e7eb;
    }


    .sidebar-menu {
        display: flex;

        gap: 8px;

        padding: 10px;
    }


    .menu-item {
        margin-bottom: 0;

        white-space: nowrap;
    }


    .sidebar-user {
        display: none;
    }


    .main-content {
        padding: 20px;
    }


    .kpi-grid {
        grid-template-columns: 1fr;
    }


    .quick-grid {
        grid-template-columns: 1fr;
    }


    .assignment-summary {
        grid-template-columns: 1fr;
    }


    .detail-grid {
        grid-template-columns: 1fr;
    }


    .details-header {
        align-items: flex-start;

        gap: 15px;

        flex-direction: column;
    }

}

sp_widget.script:
(function() {

    // ==============================
    // Logged-in user
    // ==============================

    data.userName = gs.getUserDisplayName();

    data.totalAssigned = 0;
    data.pending = 0;
    data.resolved = 0;
    data.feedback = 0;

    data.assignments = [];
    data.recentAssignments = [];


    // ==============================
    // Find Mess Staff group
    // ==============================

    var groupGR = new GlideRecord('sys_user_group');

    groupGR.addQuery('name', 'Mess Staff');
    groupGR.setLimit(1);
    groupGR.query();


    if (!groupGR.next()) {

        gs.info('CampusFood AI: Mess Staff group not found.');

        return;
    }


    var groupID = groupGR.getUniqueValue();


    // ==============================
    // Get Food Complaint records
    // Assignment Group = Mess Staff
    // State != Closed
    // ==============================

    var complaintGR = new GlideRecord(
        'x_snc_campus_foo_1_food_complaint'
    );


    complaintGR.addQuery(
        'assignment_group',
        groupID
    );


    // Standard ServiceNow Task:
    // 3 = Closed Complete
    complaintGR.addQuery(
        'state',
        '!=',
        '3'
    );


    complaintGR.orderByDesc('sys_created_on');

    complaintGR.query();


    while (complaintGR.next()) {

        var record = {};


        // ==============================
        // Basic information
        // ==============================

        record.sys_id =
            complaintGR.getUniqueValue();


        record.number =
            complaintGR.getDisplayValue('number');


        // ==============================
        // Student
        // ==============================

        record.student =
            complaintGR.getDisplayValue('student');


        // ==============================
        // Problem
        // ==============================

        record.problem =
            complaintGR.getDisplayValue('problem_type');


        // ==============================
        // Mess Hall
        // ==============================

        record.mess =
            complaintGR.getDisplayValue('mess_hall');


        // ==============================
        // Meal
        // ==============================

        record.meal =
            complaintGR.getDisplayValue('meal_type');


        // ==============================
        // Priority
        // ==============================

        record.priority =
            complaintGR.getDisplayValue('priority');


        // ==============================
        // State
        // ==============================

        record.status =
            complaintGR.getDisplayValue('state');


        // ==============================
        // Description
        // ==============================

        record.description =
            complaintGR.getDisplayValue('description');


        // ==============================
        // Add record to assignments
        // ==============================

        data.assignments.push(record);

    }


    // ==============================
    // Total Assigned
    // ==============================

    data.totalAssigned =
        data.assignments.length;


    // ==============================
    // Count Pending
    // ==============================

    for (var i = 0; i < data.assignments.length; i++) {

        var currentStatus =
            data.assignments[i].status.toLowerCase();


        if (currentStatus.indexOf('pending') !== -1) {

            data.pending++;

        }

    }


    // ==============================
    // Recent Assignments
    // ==============================

    for (
        var j = 0;
        j < data.assignments.length && j < 5;
        j++
    ) {

        data.recentAssignments.push(
            data.assignments[j]
        );

    }


    // ==============================
    // Feedback
    // ==============================
    // Feedback integration will be
    // connected after the feedback
    // relationship field is confirmed.

    data.feedback = 0;


})();
